weak_ciphers := {"ECB", "_CBC_", "CBC_SHA", "RSA_WITH_AES_128_CBC_SHA", "RSA_WITH_AES_256_CBC_SHA", "TLS_RSA_WITH_AES_128_CBC_SHA", "TLS_RSA_WITH_AES_256_CBC_SHA", "CBC"}

weak_crypto_keywords := {"encryption", "cipher", "algorithm", "crypto", "hash", "digest", "checksum", "ssl_policy", "tls_policy", "tls_version", "signature_algorithm", "key_exchange", "kms_key_id", "master_key", "encryption_key", "password_hash", "secret_hash", "encrypt"}

suspicious_attributes := {"encrypt", "encryption", "cipher", "algorithm", "hash", "digest", "cipher_suites", "ssl_policy", "tls_policy", "signature_algorithm"}

check_weak_crypto_string(str) {
    alg := weak_algorithms[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [alg]), str)
}

check_weak_crypto_string(str) {
    cipher := weak_ciphers[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [cipher]), str)
}

is_suspicious_attr_name(name) {
    kw := suspicious_attributes[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [kw]), name)
}

has_weak_crypto_in_value(node) {
    walk(node, [_, n])
    n.ir_type == "String"
    check_weak_crypto_string(n.value)
}

