weak_ciphers := {"ECB", "CBC", "SSL", "TLSv1.0", "TLSv1.1", "SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1"}

crypto_keywords_anywhere := {"encrypt", "encryption", "cipher", "algorithm", "crypto", "hash", "digest", "checksum", "ssl_policy", "tls_policy", "tls_version", "signature_algorithm", "key_exchange", "kms_key_id", "master_key", "encryption_key", "password_hash", "secret_hash", "cipher_suites", "ssl_protocol", "min_tls_version"}

password_keywords := {"password", "secret", "key", "credential", "token"}

crypto_attr_keywords := {"encrypt", "encryption", "cipher", "algorithm", "hash", "digest", "crypto", "ssl", "tls", "signature"}

check_weak_algorithm(str) {
    alg := weak_algorithms[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [alg]), str)
}

check_weak_cipher(str) {
    cipher := weak_ciphers[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [cipher]), str)
