}

has_crypto_attr_keyword(str) {
    kw := crypto_attr_keywords[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [kw]), str)
}

has_password_keyword(str) {
    kw := password_keywords[_]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [kw]), str)
}

has_weak_crypto_in_string(value) {
    value.ir_type == "String"
    check_weak_algorithm(value.value)
} else {
    value.ir_type == "String"
    check_weak_cipher(value.value)
}

has_weak_crypto_in_function(value) {
    value.ir_type == "FunctionCall"
    func_name := lower(value.name)
    contains(func_name, "hash")

    some i
    arg := value.args[i]
    arg.ir_type == "String"
    check_weak_algorithm(arg.value)
}

has_weak_crypto_in_function(value) {
    value.ir_type == "FunctionCall"
